Object.entries(PAGE_T).forEach(([lang,vals])=>Object.assign(T[lang],vals));

function guess(){const s=localStorage.getItem("aopw-lang");if(s&&T[s])return s;const n=navigator.language||"en";if(/^zh-(TW|HK)/i.test(n))return"zh-Hant";if(/^zh/i.test(n))return"zh-Hans";return LANGS.find(x=>n.startsWith(x[0]))?.[0]||"en"}
function apply(lang){document.documentElement.lang=lang;document.querySelectorAll("[data-i18n]").forEach(el=>{const k=el.dataset.i18n;if(T[lang]?.[k])el.textContent=T[lang][k]});document.querySelectorAll("[data-i18n-placeholder]").forEach(el=>{const k=el.dataset.i18nPlaceholder;if(T[lang]?.[k])el.placeholder=T[lang][k]});localStorage.setItem("aopw-lang",lang);window.dispatchEvent(new CustomEvent("aopw-language",{detail:{lang}}))}
(function(){document.querySelectorAll("nav a").forEach((a,i)=>{const keys=["nav_outbreak","nav_travel","nav_history","nav_research","nav_sources","nav_credits"];if(keys[i])a.dataset.i18n=keys[i]});const s=document.getElementById("lang");if(s){s.innerHTML=LANGS.map(x=>'<option value="'+x[0]+'">'+x[1]+'</option>').join("");s.value=guess();s.addEventListener("change",()=>apply(s.value));apply(s.value)}})();